def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    fours = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    if not fours:
        return out

    # Erase the 6 marker.
    for r, c in sixes:
        out[r][c] = 0

    r0 = min(r for r, c in fours)
    r1 = max(r for r, c in fours)
    c0 = min(c for r, c in fours)
    c1 = max(c for r, c in fours)

    if sixes:
        sr0 = min(r for r, c in sixes)
        sr1 = max(r for r, c in sixes)
        sc0 = min(c for r, c in sixes)
        sc1 = max(c for r, c in sixes)
        shape = {(r - sr0, c - sc0) for r, c in sixes}
        sh, sw = sr1 - sr0 + 1, sc1 - sc0 + 1

        # A T-shaped marker indicates a horizontal reflection.
        if sh == 3 and sw == 3 and shape == {(0, 0), (0, 1), (0, 2), (1, 1), (2, 1)}:
            side = "right"
        elif sh == 3 and sw == 3 and shape == {(0, 1), (1, 1), (2, 0), (2, 1), (2, 2)}:
            side = "left"
        elif c1 - c0 + 1 > r1 - r0 + 1:
            # For the cross marker, its horizontal offset selects above/below.
            fcenter = sum(c for r, c in fours) / len(fours)
            scenter = sum(c for r, c in sixes) / len(sixes)
            side = "up" if scenter - fcenter > 2 else "down"
        else:
            side = "right"
    else:
        side = "down"

    for r, c in fours:
        if side == "down":
            rr, cc = 2 * r1 + 1 - r, c
        elif side == "up":
            rr, cc = 2 * r0 - 1 - r, c
        elif side == "right":
            rr, cc = r, 2 * c1 + 1 - c
        else:  # left
            rr, cc = r, 2 * c0 - 1 - c
        if 0 <= rr < h and 0 <= cc < w:
            out[rr][cc] = 4

    return out
